(* [comment removed for export] *)
Theorem rta_frame_release : exists (Σ' : rtsA) (fl : Z), rw_cells asegs m fl [C1 (Z_to_bv 8 1)]
  /\ ~ aclient (live Σ) (frames Σ) USTACK_TOP fl /\ 0 < fl /\ fl + 1 <= rtA_sp0 Σ - STACK_WIN
  /\ ro_cells asegs m (f + fs_size k - 8) [C8 (Z_to_bv 64 fl)]
  /\ forall m', munch [(fl, fl + 1)] m m' -> wmono asegs m m' -> rw_cells asegs m' fl [C1 (Z_to_bv 8 0)] ->
       ART_A Σ' m' /\ frames Σ' = fr /\ live Σ' = live Σ /\ rtA_sp0 Σ' = rtA_sp0 Σ /\ credit Σ' = credit Σ
